const folkDancesData={an:{name:"Nicobari Dance",history:"A traditional dance of the Nicobarese people performed during the Ossuary Feast (pig festival). It is a way to honor the departed souls of the family.",costumes:"Dancers wear skirts made of coconut fronds and ornaments made from leaves and flowers.",festivals:"Ossuary Feast, local tribal gatherings."},ap:{name:"Kuchipudi / Vilasini Natyam",history:"While Kuchipudi is classical, Andhra has rich folk traditions like Vilasini Natyam and Dhimsa, performed by the Porja tribe of Araku Valley to celebrate the harvest.",costumes:"Brightly colored sarees with heavy tribal jewelry for women, and traditional dhotis for men.",festivals:"Itika Pongal, harvest festivals."},ar:{name:"Bardo Chham",history:"A folk dance of the Sherdukpen tribe of West Kameng. It depicts the triumph of good over evil, where dancers enact the roles of various animals.",costumes:"Elaborate animal masks (such as deer, tiger, bird) and colorful traditional tribal wear.",festivals:"Losar, tribal festivals."},as:{name:"Bihu",history:"A vibrant and energetic folk dance of Assam related to the Bihu festival, which celebrates the advent of spring and the Assamese New Year.",costumes:"Women wear the traditional Mekhela Chador, often made of Muga silk, adorned with red motifs. Men wear a dhoti, gamocha, and a matching headgear.",festivals:"Rongali Bihu, Bhogali Bihu."},br:{name:"Jhijhiya",history:"A traditional folk dance of the Mithila region in Bihar, performed almost exclusively by women during the Navratri festival. It is a prayer for a good harvest and protection against evil spirits.",costumes:"Women wear vibrant sarees and carry earthen pots on their heads with holes and a lamp inside.",festivals:"Navratri, Dussehra."},ch:{name:"Bhangra & Giddha",history:"Shared with Punjab, these lively dances represent the agricultural life and celebratory spirit of the region.",costumes:"Brightly colored Kurta and Tehmat for men, Salwar Kameez and Phulkari for women.",festivals:"Baisakhi, Lohri."},ct:{name:"Raut Nacha",history:"A traditional dance of the Yadav community of Chhattisgarh, performed as an expression of worship and joy after Diwali.",costumes:"Dancers wear brightly colored attire with sticks in their hands, often with peacock feathers attached to their turbans.",festivals:"Dev Udhni Ekadashi (after Diwali)."},dd:{name:"Mando",history:"A musical dance form that evolved in the 19th and 20th century among the Goan Catholics, heavily influencing Daman and Diu's local culture as well.",costumes:"Traditional Indo-Western attire with men in formal suits and women in long patterned dresses.",festivals:"Local fairs, weddings."},dl:{name:"Kathak (North Indian Fusion)",history:"While a cosmopolitan hub, Delhi's local folk culture blends the traditions of neighboring Haryana, UP, and Punjab, often showcasing street theatre and festive folk fusion.",costumes:"Diverse, blending various North Indian styles.",festivals:"Republic Day Parade, Diwali, Holi."},dn:{name:"Tarpa Dance",history:"A popular folk dance of the Varli, Kokna, and Koli tribes. The dance gets its name from the 'Tarpa', a wind instrument made from a dried gourd.",costumes:"Men and women wear traditional tribal attire and dance in circles holding each other by the waist.",festivals:"Harvest season, Diwali."},ga:{name:"Fugdi",history:"A Goan folk dance performed by women in the Konkan region to take a break from their daily routines and celebrate various festivals.",costumes:"Traditional nine-yard sarees tied in a specific Goan style.",festivals:"Ganesh Chaturthi, Vrata, and other agricultural festivals."},gj:{name:"Garba & Dandiya Raas",history:"Garba is a joyful circular dance performed to honor the Goddess Amba. Dandiya Raas involves dancing with decorated sticks and traces its roots to Lord Krishna's playful dance.",costumes:"Women wear Chaniya Choli adorned with mirrors and embroidery. Men wear Kediyu and Dhoti.",festivals:"Navratri."},hp:{name:"Nati",history:"A popular folk dance of Himachal Pradesh, holding the Guinness World Record as the largest folk dance. It is performed in a circular chain.",costumes:"Traditional woolen attire, long coats (Chola), and distinctive Himachali caps adorned with flowers.",festivals:"Dussehra, local fairs, New Year."},hr:{name:"Saang",history:"Also known as Swang, this is a popular folk dance-theatre form of Haryana involving dialogue, song, and dance, usually depicting mythological or historical stories.",costumes:"Traditional Haryanvi Kurta, Dhoti, and pagri for men; colorful ghagra and kurti for women.",festivals:"Holi, local melas."},jh:{name:"Jhumar / Chhau",history:"Jhumar is a popular harvest dance, while Seraikella Chhau is a martial, mask-based dance that enacts episodes from epics like the Mahabharata.",costumes:"For Chhau, dancers wear elaborately crafted masks and rich traditional costumes. Jhumar features colorful regional attire.",festivals:"Harvest festivals, Spring festivals."},jk:{name:"Rouf",history:"A traditional spring dance of Kashmir performed mostly by women. It involves simple footwork and poetic songs, welcoming the spring season.",costumes:"Women wear the traditional 'Pheran' with intricate embroidery and heavy silver jewelry.",festivals:"Eid, Ramzan, Spring arrival."},ka:{name:"Yakshagana",history:"A traditional folk theater form of coastal Karnataka combining dance, music, dialogue, and heavy makeup, often telling stories from Hindu epics.",costumes:"Elaborate, towering headgear, heavy facial makeup, and colorful, bulky costumes.",festivals:"Post-harvest season, temple festivals."},kl:{name:"Theyyam / Thiruvathirakali",history:"Theyyam is a ritualistic performance art of northern Kerala. Thiruvathirakali is a graceful group dance performed by women.",costumes:"Theyyam features striking body paint, massive headdresses, and vibrant red garments. Thiruvathirakali uses the traditional white Kerala Kasavu saree.",festivals:"Onam, Thiruvathira, temple festivals."},ld:{name:"Lava Dance",history:"The most popular traditional dance of Lakshadweep, mainly performed by the men of Minicoy island.",costumes:"Dancers wear multi-colored costumes, a distinctive headgear called 'Bolufey', and carry a drum.",festivals:"Festive occasions and island celebrations."},mh:{name:"Lavani",history:"A vibrant, energetic dance form native to Maharashtra known for its powerful rhythm. It is performed to the beats of the Dholki.",costumes:"Women wear traditional nine-yard sarees (Nauvari) and heavy jewelry, including nose rings (Nath) and ghungroos.",festivals:"Ganesh Chaturthi, local jatras (fairs)."},ml:{name:"Nongkrem",history:"A harvest thanksgiving dance of the Khasi tribe in Meghalaya, honoring the powerful Goddess Ka Blei Synshar for a good harvest and peace.",costumes:"Men wear silk turbans and carry a sword. Women wear expensive silk costumes and heavy gold/silver jewelry.",festivals:"Nongkrem Dance Festival."},mn:{name:"Pung Cholom",history:"A highly energetic dance that is the soul of Manipuri Sankirtana music. It involves dancing while playing the 'Pung' (a hand-beaten drum).",costumes:"White dhoti and a turban, playing the Pung drum strapped to the body.",festivals:"Holi (Yaoshang), religious processions."},mp:{name:"Matki",history:"A popular folk dance of the Malwa region in Madhya Pradesh, usually performed by women during weddings and birthdays, balancing earthen pots (matkis) on their heads.",costumes:"Colorful lehenga cholis with veils and heavy silver jewelry.",festivals:"Weddings, Malwa Utsav."},mz:{name:"Cheraw (Bamboo Dance)",history:"A traditional cultural dance of Mizoram where men move bamboo staves in rhythmic beats while women step in and out of the bamboo blocks.",costumes:"Vibrant traditional Mizo garments such as Puanchei, Kawrchei, and Vakiria.",festivals:"Chapchar Kut (Spring festival)."},nl:{name:"Hornbill Dance / Naga Dances",history:"The Naga tribes have various war and harvest dances characterized by chanting, rhythmic stepping, and imitating animals like the hornbill.",costumes:"Elaborate tribal warrior costumes, spears, shields, and headgear decorated with feathers and boar tusks.",festivals:"Hornbill Festival, Moatsu Mong."},or:{name:"Odissi / Ghumura",history:"Besides classical Odissi, Odisha is famous for Ghumura, a folk dance of Kalahandi district with martial arts origins.",costumes:"Dancers wear traditional dhotis, tribal ornaments, and play the Ghumura (a pitcher-shaped drum).",festivals:"Nuakhai, Kalahandi Utsav."},pb:{name:"Bhangra",history:"A lively and dynamic dance that originated in the Punjab region as a celebratory dance for the harvest season. It is characterized by high-energy leaps and the beat of the dhol.",costumes:"Men wear colorful Kurta, Tehmat (lungi), and Pagri (turban).",festivals:"Baisakhi, Lohri, weddings."},py:{name:"Garadi",history:"A popular folk dance of Puducherry, known for its mythological origins connected to the Ramayana, where monkeys celebrated Lord Rama's victory.",costumes:"Dancers dress up as monkeys with iron rings (Anjali) on their legs and carry sticks.",festivals:"Temple festivals, local celebrations."},rj:{name:"Ghoomar",history:"A traditional women's folk dance of Rajasthan, known for its graceful pirouetting which reveals the spectacular colors of the flowing skirts.",costumes:"Women wear vibrant, embroidered Ghagras (flowing skirts) and Odhnis, along with traditional silver jewelry.",festivals:"Teej, Gangaur, Navratri, weddings."},sk:{name:"Singhi Chham (Snow Lion Dance)",history:"A traditional Sikkimese dance where performers wear a snow lion costume, a cultural symbol representing the snowy peaks of Kanchenjunga.",costumes:"Elaborate, furry Snow Lion costumes operated by two dancers.",festivals:"Pang Lhabsol, Losar."},tg:{name:"Perini Sivatandavam",history:"An ancient dance form of Telangana that originated during the Kakatiya dynasty. It is a warrior dance performed by males to invoke Lord Shiva.",costumes:"Traditional dhotis, rudraksha beads, and ash smeared on the body.",festivals:"Maha Shivaratri, cultural festivals."},tn:{name:"Kummi & Karakattam",history:"Kummi is a women's dance with rhythmic clapping, often performed without musical instruments. Karakattam involves balancing decorated pots on the head.",costumes:"Traditional Kanjeevaram sarees and temple jewelry.",festivals:"Pongal, Mariamman temple festivals."},tr:{name:"Hojagiri",history:"A traditional folk dance of the Reang (Bru) clan of Tripura. Women balance a bottle and a lit lamp on their head while executing intricate lower-body movements.",costumes:"Traditional Reang attire called Rignai and Risa, with heavy coin necklaces.",festivals:"Hojagiri festival, Durga Puja."},up:{name:"Charkula / Raslila",history:"Charkula is a dramatic dance from the Braj region where veiled women balance a large multi-tiered wooden pyramid with 108 oil lamps on their heads. Raslila depicts the playful dances of Lord Krishna.",costumes:"Bright, traditional Lehenga Cholis for women, often veiled.",festivals:"Holi (especially in Mathura/Vrindavan)."},ut:{name:"Choliya",history:"A traditional folk dance of the Kumaon region in Uttarakhand. It is a sword dance with martial origins, often performed at weddings to ward off evil spirits.",costumes:"Dancers wear traditional Rajput attire, carrying a sword and a shield.",festivals:"Weddings, regional fairs."},wb:{name:"Chhau (Purulia) / Baul",history:"Purulia Chhau is a highly athletic martial dance utilizing somersaults and large masks. Baul is a mystic musical tradition.",costumes:"Elaborately painted, large papier-mâché masks and colorful costumes for Chhau.",festivals:"Chaitra Parva, Sun Festival."}};